**config.js**
```javascript
const fs = require('fs');

const JSON_CONFIG_FILE = 'config.json';

function readConfig(filePath) {
  try {
    return JSON.parse(fs.readFileSync(filePath, 'utf8'));
  } catch (err) {
    console.error(err);
    process.exit(1);
  }
}

module.exports = {
  readConfig: function() {
    return readConfig(JSON_CONFIG_FILE);
  }
};
```

**config.json**
```json
{
  "key1": "value1",
  "Key2": "value2",
  "KEY2": "newValue2"
}
```

**OverridableConfig.js**
```javascript
const os = require('os');
const { readConfig } = require('./config');

function readConfig(filePath) {
  return readConfig(filePath).then(config => {
    const settings = config;
    const overrideSettings = {};

    const envVars = new Set(os.env);

    Object.keys(settings).forEach(key => {
      if (envVars.has(key.toUpperCase().replace(/_([A-Z])/g, '$1')) && envVars.has(key)) {
        overrideSettings[key.toUpperCase().replace(/_([A-Z])/g, '$1') = settings[key];
      } else {
        overrideSettings[key] = settings[key];
      }
    });

    return overrideSettings;
  });
}

module.exports = { readConfig };
```

Here's an explanation of how this code works:

1.  We first read the JSON config file.
2.  We load the settings from the JSON file and store them in the `settings` object.
3.  We create a set with the environment variables from the current operating system.
4.  We iterate through the `settings` object's keys, looking for keys that match the uppercase version of the environment variable names.
5.  If a matching key is found, we override its value using the environment variable with the uppercase version. If not, we keep the original value.
6.  Finally, we update our node.js run-time configuration with the overridden settings.

Here's an example of how to use this function:

**Using the reducer.js**

```javascript
