Since you have nearly identical functions handling different file formats, it's perfectly fine to have a single class with a format parameter. Here's a refactored version of your functions:

```python
import os
import json
import yamlet
import toml
import configparser

class FileFormatter:
    def __init__(self, format):
        self.format = format
        self.format_params = {
            'csv': {'sep': ',', 'enc': "\"", 'quotechar': '"' },
            'json': {'sep': '\t', 'quotechar': '"' }
        }

    def csv(self, filename):
        """Handle CSV file."""
        return self._handle_csv(filename)
    def json(self, filename):
        """Handle JSON file."""
        return self._handle_json(filename)
    def xml(self, filename):
        """Handle XML file."""
        return self._handle_xml(filename)
    def yaml(self, filename):
        """Handle YAML file."""
        return self._handle_yamlet(filename)
    def toml(self, filename):
        """Handle TOML file."""
        return self._handle_toml(filename)


    def _handle_file(self, filename):
        """
        Reads the provided file and returns its contents, 
        or raises an error if the file does not exist or is of specified format.

        Args:
        - filename: The name of the file to read.

        Raises:
        - ValueError: If the file is of the wrong format.
        - FileNotFoundError: If the file does not exist.

        Returns:
        - The contents of the file.
        """
        if not os.path.exists(filename):
            raise FileNotFoundError("File not found")

        file_type = filename.lower()

        if file_type in self.format_params[self.format]:
            file_type_content = self.format_params[self.format][file_type]
            try:
                with open(filename, 'r', encoding=self.format['enc']) as file_pointer:
                    return file_pointer.read()
            except LookupError:
                raise ValueError(f"File of the specified type {file_type} does not exist")
        else:
            raise ValueError(f"Unknown file format {file_type}")

    def _handle_csv(self, filename):
        return self.csv(filename)

    def _handle_json(self, filename):
        return self.json(filename)

    def _handle_xml(self, filename):
        return self.xml(filename)

    def _handle_yamlet(self, filename):
        return self.yml(filename)

    def _handle_toml(self, filename):
        return self.toml(filename)

def main():
    print("Removal of independent functions")
    formatter = FileFormatter('csv')
    print(formatter.csv("example.csv"))

    print("\nRemoval of independent functions")
    formatter = FileFormatter('json')
    try:
        print(formatter.json("example.json"))
    except ValueError as e:
        print(e)

    print("\nRemoval of independent functions")
    formatter = FileFormatter('xml')
    try:
        print(formatter.xml("example.xml"))
    except ValueError as e:
        print(e)

    print("\nRemoval of independent functions")
    formatter = FileFormatter('yaml')
    try:
        print(formatter.yml("example.yaml"))
    except ValueError as e:
        print(e)

    print("\nRemoval of independent functions")
    formatter = FileFormatter('toml')
    try:
        print(formatter.toml("example.toml"))
    except ValueError as e:
        print(e)

    print("\nRemoval of independent functions")
    with FileFormatter('ini') as formatter:
        print(formatter.csv("example.csv"))
        print(formatter.json("example.json"))
        print(formatter.xml("example.xml"))
        print(formatter.yaml("example.yaml"))
        print(formatter.toml("example.toml"))

if __name__ == "__main__":
    import sys
    if len(sys.argv) > 1:
        print(f"Running the script from file: {sys.argv[1]}")
    else:
        main()
```

This refactoring provides a common class `FileFormatter` with a `format` parameter that determines the file format to handle. The `_handle_file` method reads the provided file and returns its contents, raising an error if the file does not exist or is of the wrong format.

