**Step 2: Create a new file (e.g., `service.go`) to define a client**

Here's an example of what `service.go` might look like:
```go
package main

import (
    "database/sql"
    "encoding/json"
    "fmt"
    "log"

    "github.com/go-otlp/opentelemetry-go/propagation"
    "github.com/go-otlp/opentelemetry-go/propagation/trace"

    _ "github.com/go-sql-driver/mysql"
    opentelemetry/open-telemetry-go/spring"

    _ "github.com/go-sql-driver/mysql"
)

type Order struct {
    ID       int    `json:"id"`
    CustomerID int    `json:"customer_id"`
}

func main() {
    db, err := sql.Open("mysql", "username:password@tcp(localhost:3306/database?charset=utf8&parseType=ei&rank=64")
    if err != nil {
        log.Fatal(err)
    }

    defer db.Close()

    // Create a new Telemetry client with a flow name
    traced := trace.New(
        trace.WithSpanDescription("My Service",
            trace.WithActor("my_service", trace.WithServiceID("my_service", "e2f7e2b830a7efaa562b9d0c1d3450a5e68"),
            trace.WithEnv("OTEL-collector-priority", trace.Priority Normal),
            trace.WithSampler(trace.SamplingRule(TriggerAuraBestEffort, 1))
        ),
    )

    // Create users table client
    err = db.QueryRow("INSERT INTO users (id, customer_id) VALUES (1, 1)".fmtstyled(` inserting data`, "...").String()).Exec()

    if err != nil {
        log.Println(err)
        // Replace with actual error handling
    }

    // With spans for client and query execution
    withSpan := traced.WithSpan(
        trace.WithActions(
            expanded(
                propagated(
                    trace.WithSpanKind(trace.KeyspanTypeSQL, "SELECT * FROM orders WHERE id = 1"),
                    "SELECT",
                    expression: func (e *sql.DB) (sql.Result, error) (interface{}, error) {
                        row := e Rows()
                        if err := row.Scan(&order.ID, &order.CustomerID); err != nil {
                            return nil, fmt.Errorf("failed to scan row: %s", err)
                        }
                        return row, nil
                    }
                ),
                saveder: func (e *sql.DB) error {
                    // Handle any custom errors
                    if err := e.Close(); err != nil {
                        return err
                    }
                    return nil
                },
            ),
            spacingRequirements: func (opt func(), err func() error) error {
                // Additional spacing requirements
                opt(err)
                return err
            },
        ),
        "e2f7e2b830a7efaa562b9d0c1d3450a5e68", exprs: "SELECT * FROM orders WHERE id = 1")
    )

    // Wait until the span is done executing
    err = withSpan.Cause(err)

    if err != nil {
        log.Println(err)
    } else {
        // Pop the span and immediately return the result
        result, _ := withSpan.Pop().Result()

        fmt.Println(result)
    }
}
